import{_ as r,a as p,e as i,l as t,ar as l,N as o,t as n}from"./chunks/framework.BahxXRbM.js";const g=JSON.parse('{"title":"请求代理","description":"正向代理和方向代理的定义和区别","frontmatter":{"title":"请求代理","description":"正向代理和方向代理的定义和区别","tags":["network","proxy"]},"headers":[],"relativePath":"frontend/network/proxy.md","filePath":"frontend/network/proxy.md","lastUpdated":1761045430000}'),d={name:"frontend/network/proxy.md"},s={id:"frontmatter-title",tabindex:"-1"};function c(a,e,h,m,f,_){return i(),p("div",null,[e[1]||(e[1]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/frontend/network/proxy.md for this page in Markdown format",-1)),t("h1",s,[o(n(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),e[2]||(e[2]=l('<h2 id="代理" tabindex="-1">代理 <a class="header-anchor" href="#代理" aria-label="Permalink to “代理”">​</a></h2><p>代理就相当于中间商，本来A和B是可以直接连接的，但是此时添加了一个C在中间，A跟B不直接连接，而是通过C作为中介进行连接。最常见的例子就是二手东，其实很多我们租房子时签约的人不是房子的真正房东，而是房东委托的中介，房东不想管事或者房子太多，只靠自己无法进行管理，所以才会通过中介( 代理)进行处理，像蛋壳、自如这样的租房软件其实也是中介的一种，真正的房东是直接将房子委托给这样的第三方中介进行出租。</p><p>一个完整的请求是由: client(客户端) -&gt; proxy(代理) -&gt; server(服务端) 组成。</p><h3 id="正向代理" tabindex="-1">正向代理 <a class="header-anchor" href="#正向代理" aria-label="Permalink to “正向代理”">​</a></h3><p>正向代理: 顺着请求的方向进行的代理，即代理服务器它是由你配置为你服务，去请求目标服务器地址。</p><p>举例一: 如我们现在想要访问谷歌，但是由于某些原因，无法直接访问到谷歌，我们可以通过连接一台代理服务器，代理服务将我们的请求提交到谷歌，然后再将谷歌的响应反馈给我们，对于谷歌而言，它只知道有一个请求过来，但是它并不会知道我们是无法直接访问它的。</p><p><img src="https://pic1.zhimg.com/v2-8bcb5360b9edd2f7a650ef70fac42a38_1440w.jpg" alt="" loading="lazy"></p><p>正向代理的作用:</p><ol><li><p>访问原来无法访问的资源，如 google</p></li><li><p>可以做缓存，加速访问资源</p></li><li><p>对客户端访问授权，上网进行认证</p></li><li><p>代理可以记录用户访问记录（<a href="https://zhida.zhihu.com/search?content_id=124566892&amp;content_type=Article&amp;match_order=1&amp;q=%E4%B8%8A%E7%BD%91%E8%A1%8C%E4%B8%BA%E7%AE%A1%E7%90%86&amp;zhida_source=entity" target="_blank" rel="noreferrer">上网行为管理</a>），对外隐藏用户信息</p></li></ol><h3 id="反向代理" tabindex="-1">反向代理 <a class="header-anchor" href="#反向代理" aria-label="Permalink to “反向代理”">​</a></h3><p>反向代理: 跟正向代理相反，它是为目标服务器进行服务的，但是请求的流程还是: client -&gt; proxy -&gt; server。</p><p>举例: 比如我们访问百度网站，百度的代理服务器对外的域名为 <a href="https://www.baidu.com" target="_blank" rel="noreferrer">https://www.baidu.com</a> 。具体内部的服务器节点我们不知道。现实中我们通过访问百度的代理服务器后，代理服务器给我们转发请求到他们N多的服务器节点中的一个给我们进行搜索后将结果返回，此时，代理服务器对我们客户端来说就充当了提供响应的服务器，但是对于目标服务器来说，它只是进行了一个请求和转发的功能。</p><p><img src="https://pic4.zhimg.com/v2-8e2bc94b0415da303730a572fd6e0121_1440w.jpg" alt="" loading="lazy"></p><p>反向代理的作用:</p><ol><li><p>保证内网的安全，阻止web攻击，大型网站，通常将反向代理作为公网访问地址，Web服务器是内网。</p></li><li><p>负载均衡，通过反向代理服务器来优化网站的负载。</p></li></ol><h3 id="区别与联系" tabindex="-1">区别与联系 <a class="header-anchor" href="#区别与联系" aria-label="Permalink to “区别与联系”">​</a></h3><p><img src="https://pic3.zhimg.com/v2-d0f22453818a20bf83ef62ecc32c64b2_1440w.jpg" alt="" loading="lazy"></p><p>区别：</p><ul><li><p>正向代理即客户端代理，代理客户端，服务端不知道实际发起请求的客户端.</p></li><li><p>反向代理即服务端代理，代理服务端，客户端不知道实际提供服务的服务端.</p></li></ul><p>联系:</p><ul><li><p>正向代理中，proxy 和 client 同属一个 LAN，对 server 透明；</p></li><li><p>反向代理中，proxy 和 server 同属一个 LAN，对 client 透明。</p></li></ul><p>事实上，正向代理和反向代理的作用都是进行请求和转发，但是为了区别正向代理，所以后出现的就成为反向代理。</p><p>生活中最常见的例子:</p><p>1、正向代理: 卖票的黄牛</p><p>2、反向代理: 出租房的二手东</p>',25))])}const y=r(d,[["render",c]]);export{g as __pageData,y as default};
